def read(path):
    return json.loads(path.read_text())

def put(name, obj):
    path = DIR / name
    path.parent.mkdir(parents=True, exist_ok=True)
    data = obj if isinstance(obj, bytes) else (obj if isinstance(obj, str) else json.dumps(obj, ensure_ascii=False, indent=2) + '\n').encode()
    if path.exists():
        assert path.read_bytes() == data, f'Frozen/preexisting file differs: {path}'
    else:
        path.write_bytes(data)
    return path.relative_to(ROOT).as_posix()

def bind(path):
    return {'path': path.relative_to(ROOT).as_posix(), 'sha256': hashlib.sha256(path.read_bytes()).hexdigest(), 'bytes': path.stat().st_size}

